UPDATE safety_inspection_items
SET result = #{result},
    comment = #{comment},
    checked_at = #{checkedAt}
WHERE id = #{itemId}
  AND safety_inspection_id = #{inspectionId}

mapper.select:
SELECT COUNT(*)
FROM safety_inspection_items
WHERE safety_inspection_id = #{inspectionId}

mapper.update:
UPDATE safety_inspections
SET status = #{status},
    comment = #{comment},
    completed_at = #{completedAt}
